  function chooser9(){return breadcrumb('راهنمای انتخاب')+`<section class="shell chooser-intro"><span class="eyebrow">GUIDED EQUIPMENT SELECTION</span><h1>نیازتان را روشن‌تر کنید.</h1><p>این راهنما خانوادهٔ مرتبط را بر اساس نوع کاربرد نشان می‌دهد؛ اطلاعات فنی شما برای بررسی کارشناس همراه درخواست قرار می‌گیرد.</p></section><section class="shell chooser-layout"><aside class="chooser-sidebar"><h2>مسیر انتخاب</h2><ol class="wizard-steps">${['نوع کاربرد','قطعه و متریال','نیاز تولید','نتیجهٔ اولیه'].map((s,i)=>`<li data-wizard-step="${i}"><span>${num(i+1)}</span><div><b>${s}</b><small>${['چه کاری انجام می‌دهید؟','با چه قطعه‌ای کار می‌کنید؟','گردش کارتان چگونه است؟','مرور گزینه‌ها و درخواست'][i]}</small></div></li>`).join('')}</ol><div class="wizard-sidebar-note">${icon('head')}<p>نام مدل به‌تنهایی کافی نیست. توان، ابعاد و پیکربندی باید با قطعه و شرایط کار تطبیق داده شوند.</p></div></aside><div class="wizard-main"><div class="wizard-progress" role="progressbar" aria-label="پیشرفت راهنمای انتخاب" aria-valuemin="1" aria-valuemax="4" aria-valuenow="1"><span></span></div><div id="wizard-screen"></div></div></section>`;}
  function wizardSummary9(){const u=getUse9();return [u?'کاربرد: '+u.name:'',wizard9.use==='parts'?'خانوادهٔ قطعه: '+label(wizard9.part):'متریال: '+formLabel9(materials9,wizard9.material),wizard9.thickness?'ضخامت اعلامی: '+wizard9.thickness+' میلی‌متر':'',wizard9.width?'عرض اعلامی: '+wizard9.width+' میلی‌متر':'',wizard9.length?'طول اعلامی: '+wizard9.length+' میلی‌متر':'',wizard9.model?'مدل دستگاه موجود: '+wizard9.model:'','حجم کار: '+formLabel9(volumes9,wizard9.volume),wizard9.format?'توضیح گردش کار: '+wizard9.format:'',wizard9.note?'توضیحات: '+wizard9.note:''].filter(Boolean);}
  function wizardContent9(){
    const u=getUse9();
    if(wizardStep9===0)return `<form id="wizard-form"><span class="wizard-step-label">گام ${num(1)} از ${num(4)}</span><h2 tabindex="-1" class="wizard-heading">چه کاری می‌خواهید انجام دهید؟</h2><p>کاربرد اصلی را انتخاب کنید. در ادامه دربارهٔ قطعه و شرایط کار می‌پرسیم.</p><fieldset class="wizard-use-grid"><legend class="sr-only">نوع کاربرد</legend>${uses9.map(x=>`<label class="choice-tile"><input type="radio" name="use" value="${x.id}" ${wizard9.use===x.id?'checked':''} required><span class="choice-tile-body">${icon(x.icon)}<span><b>${x.name}</b><small>${x.text}</small></span></span></label>`).join('')}</fieldset><div class="wizard-navigation"><span>گزینه‌های مرتبط در پایان نمایش داده می‌شوند.</span><button type="submit" class="button primary">ادامه</button></div></form>`;
    if(wizardStep9===1)return `<form id="wizard-form"><span class="wizard-step-label">گام ${num(2)} از ${num(4)}</span><h2 tabindex="-1" class="wizard-heading">${wizard9.use==='parts'?'دربارهٔ قطعه و دستگاه فعلی':'دربارهٔ قطعه و متریال'}</h2><p>${u.text}</p>${wizard9.use==='parts'?`<fieldset class="material-options"><legend>کدام خانوادهٔ تجهیزات را بررسی می‌کنید؟</legend>${[['parts','چیلر و تجهیزات جانبی'],['source','سورس لیزر'],['head','هد و کنترلر'],['consumables','قطعات مصرفی']].map(x=>`<label><input type="radio" name="part" value="${x[0]}" ${wizard9.part===x[0]?'checked':''} required><span>${x[1]}</span></label>`).join('')}</fieldset><label class="wizard-field">مدل دستگاه یا کد قطعهٔ فعلی<input name="model" value="${E(wizard9.model)}" maxlength="160" placeholder="در صورت اطلاع وارد کنید"></label>`:`<fieldset class="material-options"><legend>جنس اصلی قطعه چیست؟</legend>${materials9.map(x=>`<label><input type="radio" name="material" value="${x[0]}" ${wizard9.material===x[0]?'checked':''} required><span>${x[1]}</span></label>`).join('')}</fieldset><div class="dimension-fields"><label>ضخامت <small>میلی‌متر</small><input name="thickness" type="number" inputmode="decimal" min="0.01" max="100000" step="any" value="${E(wizard9.thickness)}" placeholder="اختیاری"></label><label>عرض قطعه <small>میلی‌متر</small><input name="width" type="number" inputmode="decimal" min="0.01" max="100000" step="any" value="${E(wizard9.width)}" placeholder="اختیاری"></label><label>طول قطعه <small>میلی‌متر</small><input name="length" type="number" inputmode="decimal" min="0.01" max="100000" step="any" value="${E(wizard9.length)}" placeholder="اختیاری"></label></div><p class="field-hint">این اعداد به درخواست شما اضافه می‌شوند؛ از آن‌ها برای تأیید ظرفیت مدل‌ها استفاده نمی‌شود.</p>`}<div class="wizard-navigation"><button type="button" class="button secondary" data-wizard-back>مرحلهٔ قبل</button><button type="submit" class="button primary">ادامه</button></div></form>`;
    if(wizardStep9===2)return `<form id="wizard-form"><span class="wizard-step-label">گام ${num(3)} از ${num(4)}</span><h2 tabindex="-1" class="wizard-heading">کار شما چگونه پیش می‌رود؟</h2><p>نوع و تکرار سفارش، به شناخت شرایط استفاده از دستگاه کمک می‌کند.</p><fieldset class="volume-options"><legend>حجم و تکرار کار</legend>${volumes9.map(x=>`<label><input type="radio" name="volume" value="${x[0]}" ${wizard9.volume===x[0]?'checked':''} required><span>${x[1]}</span></label>`).join('')}</fieldset><label class="wizard-field">${wizard9.use==='cutting'?'ورق، لوله یا هر دو؟':wizard9.use==='marking'?'چگونه قطعه را قرار می‌دهید؟':'نیاز ویژهٔ فرایند'}<input name="format" value="${E(wizard9.format)}" maxlength="200" placeholder="${wizard9.use==='cutting'?'مثلاً ورق و گاهی پروفیل':wizard9.use==='marking'?'مثلاً روی میز یا در خط تولید':'در صورت نیاز توضیح دهید'}"></label><label class="wizard-field">توضیح تکمیلی<textarea name="note" rows="3" maxlength="1000" placeholder="نوع سفارش، نیاز خاص یا سؤال فنی…">${E(wizard9.note)}</textarea></label><div class="wizard-navigation"><button type="button" class="button secondary" data-wizard-back>مرحلهٔ قبل</button><button type="submit" class="button primary">دیدن نتیجهٔ اولیه</button></div></form>`;
    const needsReview=wizard9.material==='nonmetal'&&['cutting','welding'].includes(wizard9.use),cat=wizard9.use==='parts'?wizard9.part:u.cat;
    const choices=needsReview?[]:D.products.filter(p=>p.cat===cat).slice(0,6);
    return `<div class="wizard-result"><span class="wizard-step-label">گام ${num(4)} از ${num(4)}</span><span class="result-symbol">${icon(needsReview?'head':'check')}</span><h2 tabindex="-1" class="wizard-heading">${needsReview?'این کاربرد به بررسی تخصصی نیاز دارد.':'خانوادهٔ مرتبط با کاربرد شما'}</h2><p>${needsReview?'برای قطعهٔ غیرفلزی، از این کاتالوگ برش یا جوش فایبر، مدل مناسبی تأیید نمی‌کنیم. اطلاعات قطعه را برای بررسی راهکار به کارشناس بفرستید.':`بر اساس نوع کاربرد، خانوادهٔ «${label(cat)}» برای آشنایی اولیه نمایش داده شده است. توان، ضخامت و ظرفیت این مدل‌ها با نیاز شما تطبیق داده نشده‌اند.`}</p><div class="wizard-result-summary"><h3>آنچه برای بررسی اعلام کردید</h3>${wizardSummary9().map(t=>`<p>${E(t)}</p>`).join('')}</div><div class="button-row"><button class="button primary" data-quote="GUIDED_SELECTION">ارسال نیاز برای بررسی فنی</button><button class="button secondary" data-wizard-restart>ویرایش پاسخ‌ها</button></div>${choices.length?`<div class="wizard-result-products"><h3>مدل‌هایی برای مرور اولیه</h3><div class="product-grid">${choices.map(p=>card(p)).join('')}</div><a class="text-link" href="products.html?cat=${cat}">همهٔ محصولات این خانواده</a></div>`:''}</div>`;
  }
  function basketPage9(){return breadcrumb('سبد استعلام')+pageIntro('YOUR EQUIPMENT SHORTLIST','مدل‌های منتخب، در یک درخواست.','تعداد و یادداشت سفارش را مشخص کنید؛ این سبد برای استعلام است و پرداخت اینترنتی انجام نمی‌دهد.')+`<section class="shell basket-layout" id="basket-content">${basketContent9()}</section>`;}
  function basketContent9(){if(!basket9.length)return `<div class="empty-basket"><span>${bagIcon9()}</span><h2>سبد استعلام هنوز خالی است.</h2><p>از کاتالوگ، محصولاتی را که می‌خواهید بررسی کنید به این فهرست اضافه کنید.</p><a class="button primary" href="products.html">دیدن کاتالوگ محصولات</a><a class="text-link" href="chooser.html">کمک برای انتخاب خانوادهٔ دستگاه</a></div>`;
    return `<div class="basket-items"><div class="basket-heading"><h2>${num(basket9.length)} مدل منتخب</h2><a class="text-link" href="products.html">ادامهٔ بررسی محصولات</a></div>${basket9.map(item=>{const p=D.products.find(p=>p.code===item.code);return `<article class="basket-item" data-basket-item="${E(p.code)}"><a class="basket-item-image" href="${href(p.code)}">${image(p)}</a><div class="basket-item-info"><span class="eyebrow">${label(p.cat)}</span><h3><a href="${href(p.code)}">${E(p.name)}</a></h3><span class="basket-item-code" dir="ltr">${E(p.code)}</span><button class="remove-inquiry" data-remove-inquiry="${E(p.code)}">حذف از سبد</button></div><div class="quantity-control"><span>تعداد درخواستی</span><div><button data-quantity="${E(p.code)}" data-change="-1" aria-label="کاهش تعداد ${E(p.code)}">−</button><output aria-label="تعداد ${E(p.code)}">${num(item.quantity)}</output><button data-quantity="${E(p.code)}" data-change="1" aria-label="افزایش تعداد ${E(p.code)}">+</button></div></div></article>`;}).join('')}<label class="basket-note">توضیح مشترک برای این درخواست<textarea id="basket-note" rows="3" maxlength="1500" placeholder="کاربرد، مشخصات قطعه یا سؤال شما…">${E(readBasketNote9())}</textarea></label></div><aside class="basket-summary"><span class="eyebrow">INQUIRY REQUEST</span><h2>آمادهٔ بررسی فنی</h2><div><span>تعداد مدل‌ها</span><b>${num(basket9.length)}</b></div><div><span>مجموع تعداد درخواستی</span><b>${num(basket9.reduce((n,x)=>n+x.quantity,0))}</b></div><p>قیمت، موجودی و سازگاری محصولات پس از بررسی درخواست اعلام می‌شود.</p><button class="button primary" data-quote="INQUIRY_BASKET">تکمیل مشخصات و ارسال</button><a class="button secondary" href="products.html">افزودن محصول دیگر</a><small>ارسال از طریق واتساپ، ایتا یا بله انجام می‌شود.</small></aside>`;
  }
  function readBasketNote9(){try{return sessionStorage.getItem('sahand-preview-12-basket-note')||'';}catch{return '';}}
  function writeBasketNote9(value){try{sessionStorage.setItem('sahand-preview-12-basket-note',value);}catch{}}
  function quoteForm(code='',embedded=false){let context=[];if(code==='INQUIRY_BASKET'){context=basket9.map(x=>{const p=D.products.find(p=>p.code===x.code);return `${p.code} — ${p.name} — تعداد: ${x.quantity}`;});if(readBasketNote9())context.push('یادداشت درخواست: '+readBasketNote9());}else if(code==='GUIDED_SELECTION'){context=wizardSummary9();}else return inheritedQuoteForm(code,embedded);
    let html=inheritedQuoteForm('',embedded);const value=context.join('\n');html=html.replace('<input type="hidden" name="product" value="">','<input type="hidden" name="product" value="'+E(value)+'">');html=html.replace('<div class="form-grid">','<div class="inquiry-context"><h3>خلاصهٔ درخواست شما</h3>'+context.map(t=>'<p>'+E(t)+'</p>').join('')+'</div><div class="form-grid">');return html;
  }
  function saveBasket9(){try{localStorage.setItem('sahand-preview-12-inquiry',JSON.stringify(basket9));}catch{}document.querySelectorAll('[data-basket-count]').forEach(x=>x.textContent=num(basketCount9()));document.querySelectorAll('[data-add-inquiry]').forEach(b=>{const added=basket9.some(x=>x.code===b.dataset.addInquiry);b.classList.toggle('is-added',added);b.setAttribute('aria-pressed',String(added));b.textContent=added?'در سبد استعلام':'+ افزودن به استعلام';});}
  function setupBuying9(){
    try{const saved=JSON.parse(sessionStorage.getItem('sahand-preview-12-guided')||'null');if(saved&&uses9.some(x=>x.id===saved.use)&&!params.get('use'))wizard9={...wizard9,...saved};}catch{}
    document.addEventListener('click',e=>{
      const quick=e.target.closest('[data-quick-use]');if(quick){document.querySelectorAll('[data-quick-use]').forEach(b=>b.setAttribute('aria-pressed',String(b===quick)));document.querySelector('.quick-start').href='chooser.html?use='+quick.dataset.quickUse;}
      const add=e.target.closest('[data-add-inquiry]');if(add){const p=D.products.find(p=>p.code===add.dataset.addInquiry);if(!p)return;if(basket9.some(x=>x.code===p.code)){location.href='basket.html';return;}if(basket9.length>=30){toast('تا ۳۰ مدل را در یک درخواست قرار دهید.');return;}basket9.push({code:p.code,quantity:1});saveBasket9();toast('محصول به سبد استعلام اضافه شد.');}
      const remove=e.target.closest('[data-remove-inquiry]');if(remove){basket9=basket9.filter(x=>x.code!==remove.dataset.removeInquiry);saveBasket9();document.getElementById('basket-content').innerHTML=basketContent9();document.querySelector('.basket-heading h2,.empty-basket h2')?.setAttribute('tabindex','-1');document.querySelector('.basket-heading h2,.empty-basket h2')?.focus();}
      const qty=e.target.closest('[data-quantity]');if(qty){const item=basket9.find(x=>x.code===qty.dataset.quantity);if(item){item.quantity=Math.max(1,Math.min(99,item.quantity+Number(qty.dataset.change)));saveBasket9();document.getElementById('basket-content').innerHTML=basketContent9();document.querySelector(`[data-quantity="${CSS.escape(item.code)}"][data-change="${qty.dataset.change}"]`)?.focus();}}
      if(e.target.closest('[data-wizard-back]')){captureWizard9();wizardStep9=Math.max(0,wizardStep9-1);renderWizard9(true);}
      if(e.target.closest('[data-wizard-restart]')){wizardStep9=0;renderWizard9(true);}
    });
    document.addEventListener('input',e=>{if(e.target.id==='basket-note')writeBasketNote9(e.target.value);});
    document.addEventListener('submit',e=>{if(e.target.id!=='wizard-form')return;e.preventDefault();if(!e.target.reportValidity())return;captureWizard9();wizardStep9=Math.min(3,wizardStep9+1);renderWizard9(true);});
    function captureWizard9(){const form=document.getElementById('wizard-form');if(form){const d=new FormData(form);for(const key of ['use','material','part','width','length','thickness','model','volume','format','note'])if(d.has(key))wizard9[key]=String(d.get(key));}try{sessionStorage.setItem('sahand-preview-12-guided',JSON.stringify(wizard9));}catch{}}
    function renderWizard9(focus=false){const screen=document.getElementById('wizard-screen');screen.innerHTML=wizardContent9();document.querySelectorAll('[data-wizard-step]').forEach(el=>{const n=Number(el.dataset.wizardStep);el.classList.toggle('is-current',n===wizardStep9);el.classList.toggle('is-complete',n<wizardStep9);if(n===wizardStep9)el.setAttribute('aria-current','step');else el.removeAttribute('aria-current');});const bar=document.querySelector('.wizard-progress');bar.setAttribute('aria-valuenow',String(wizardStep9+1));bar.querySelector('span').style.width=((wizardStep9+1)/4*100)+'%';if(focus){screen.querySelector('.wizard-heading')?.focus({preventScroll:true});screen.scrollIntoView({block:'start',behavior:'smooth'});}saveBasket9();}
    if(route==='chooser')renderWizard9();
    if(route==='product'){const p=D.products.find(p=>p.code===params.get('code'));if(p){const add=document.createElement('button');add.className='button add-to-inquiry detail-inquiry-add';add.dataset.addInquiry=p.code;add.textContent='+ افزودن به سبد استعلام';document.querySelector('.detail-copy .button-row')?.prepend(add);}}
    saveBasket9();
  }

  // Independent digital exhibition, cinematic film room and interactive engineering atlas.
  const film8 = [
    {id:'cutting',name:'برش؛ از حرکت تا قطعه',en:'THE CUTTING PROCESS',url:'https://sahandlaser.com/wp-content/uploads/2025/06/cutting.mp4',text:'فیلم فرایند برش، منتشرشده در صفحهٔ دستگاه برش سایت سهند لیزر.'},
    {id:'line',name:'نگاهی به خط محصول',en:'THE PRODUCT LINE',url:'https://sahandlaser.com/wp-content/uploads/2025/08/product-line.mp4',text:'نمایی از خط محصول در محتوای تصویری سهند لیزر.'},
    {id:'head',name:'از نزدیک؛ هد BLT310',en:'INSIDE THE CUTTING HEAD',url:'https://sahandlaser.com/wp-content/uploads/2025/08/BLT310_Shanghai-Friendess-Electronic-Technology.mp4',text:'ویدئوی معرفی هد BLT310؛ برای آشنایی با یکی از اجزای سامانهٔ برش.'}
  ];
  const poster8='https://sahandlaser.com/wp-content/uploads/2025/08/first-baner-1_807400.jpg';
  const atlasParts8=[
    {id:'source',name:'سورس لیزر',en:'LASER SOURCE',x:15,y:57,cat:'source',lead:'جایی که پرتو تولید می‌شود.',text:'سورس، انرژی الکتریکی را به تابش لیزر تبدیل می‌کند. نوع کار، جنس قطعه و فرایند تولید در انتخاب خانواده و حالت کاری منبع اثر دارند.',check:['نوع فرایند و حالت کاری منبع','سازگاری اتصال فیبر و هد','الزامات برق و خنک‌کاری'],icon:'source'},
    {id:'fiber',name:'مسیر انتقال پرتو',en:'BEAM DELIVERY',x:42,y:24,cat:'source',lead:'انتقال انرژی، تا محل فرایند.',text:'در سامانهٔ فایبر، فیبر انتقال و اتصال‌های اپتیکی، مسیر رسیدن پرتو از منبع به هد را فراهم می‌کنند. مشخصات این مسیر باید با منبع و هد سازگار باشد.',check:['نوع اتصال و رابط اپتیکی','سازگاری با سورس و هد','رعایت الزامات سازنده برای نصب'],icon:'layers'},
    {id:'head',name:'هد و اپتیک',en:'FOCUS & PROCESS',x:61,y:41,cat:'head',lead:'هدایت و متمرکزکردن پرتو.',text:'هد، اجزای اپتیکی و نازل در شکل‌گیری فرایند روی قطعه نقش دارند. در برش، تطبیق هد با توان و نوع منبع و انتخاب اجزای اپتیکی مناسب اهمیت دارد.',check:['توان قابل تحمل و نوع اتصال','فاصلهٔ کانونی و اپتیک سازگار','نازل و قطعات مصرفی مرتبط'],icon:'head'},
    {id:'bed',name:'میز و سامانهٔ حرکت',en:'MOTION & WORK AREA',x:63,y:69,cat:'cutting',lead:'مسیر طرح، روی سطح کار.',text:'شاسی، میز و محورهای حرکت، ساختار اجرای مسیر برش را تشکیل می‌دهند. ابعاد قطعه، روش بارگذاری و نیاز به برش مقطع در انتخاب تک‌میز، دومیز یا روتاری مؤثر است.',check:['ابعاد و وزن قطعه','روش بارگذاری و گردش کار','نیاز به میز دوم، کابین یا روتاری'],icon:'cut'},
    {id:'control',name:'کنترل و نرم‌افزار',en:'CONTROL SYSTEM',x:84,y:44,cat:'head',lead:'از فایل طرح تا فرمان حرکت.',text:'کنترلر و نرم‌افزار، مسیر و تنظیمات فرایند را مدیریت می‌کنند. سازگاری با سخت‌افزار، نوع دستگاه و الزامات کاربری، بخشی از بررسی فنی است.',check:['سازگاری کنترلر با دستگاه','فرمت فایل و گردش کار نرم‌افزاری','هماهنگی با سامانهٔ حرکت و هد'],icon:'mark'},
    {id:'cooling',name:'خنک‌کاری',en:'THERMAL MANAGEMENT',x:24,y:82,cat:'parts',lead:'مدیریت گرما، در کنار فرایند.',text:'چیلر و مدار خنک‌کاری باید با الزامات سورس و هد و شرایط محیط نصب تطبیق داده شوند. انتخاب صرفاً بر اساس نام یا ظاهر دستگاه کافی نیست.',check:['الزامات سازندهٔ سورس و هد','شرایط محیط و محل نصب','مشخصات مدار و ظرفیت مورد نیاز'],icon:'parts'}
  ];
  const playIcon8=()=>'<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.5"><path d="m9 5 10 7-10 7z"/></svg>';
  function exhibitionHeader(){return `<div class="utility"><div class="shell"><span>سهند لیزر / نمایشگاه تجهیزات صنعتی</span><a href="tel:+983131320012" dir="ltr">+98 31 3132 0012</a></div></div><header class="site-header"><div class="shell topline"><a class="identity" href="index.html" aria-label="صفحهٔ اصلی سهند لیزر"><span class="brand-mark">${icon('head')}</span><span>سهند لیزر<small lang="en">SAHAND LASER</small></span></a><button class="mobile-toggle icon-button" aria-label="باز کردن منو" aria-controls="main-nav" aria-expanded="false">${icon('menu')}</button><nav id="main-nav" aria-label="ناوبری اصلی"><a href="index.html" ${route==='index'?'aria-current="page"':''}>خانه</a><a href="showroom.html" ${route==='showroom'?'aria-current="page"':''}>نمایشگاه</a><a href="atlas.html" ${route==='atlas'?'aria-current="page"':''}>اطلس فنی</a><details class="mega"><summary>محصولات</summary><div class="mega-panel"><div class="mega-intro"><span class="eyebrow">THE EQUIPMENT COLLECTION</span><h2>هر کاربرد،<br>یک مسیر.</h2><a href="products.html">کاتالوگ کامل</a></div><div class="mega-links">${cats.map(c=>`<a href="products.html?cat=${c[0]}">${icon(c[3])}<span>${c[1]}<small>${c[2]}</small></span><b>${num(counts[c[0]])}</b></a>`).join('')}</div></div></details><a href="films.html" ${route==='films'?'aria-current="page"':''}>فیلم‌ها</a><a href="services.html">خدمات</a><a href="contact.html">تماس</a></nav><button class="button primary header-quote" data-quote="">گفت‌وگوی فنی</button></div></header>`;}
  function intro8(kicker,title,description){return `<div class="section-heading"><div><span class="eyebrow">${kicker}</span><h2>${title}</h2></div><p>${description}</p></div>`;}
  function exhibition8(full=false){
    const cat=counts[params.get('cat')]?params.get('cat'):'cutting';
    const ps=D.products.filter(p=>p.cat===cat),p=ps[0];
    return `<section class="exhibition ${full?'exhibition-full':''}" id="exhibition" data-showroom><div class="shell">${intro8('THE DIGITAL SHOWROOM','از نزدیک ببینید.','خانواده را انتخاب کنید؛ بین مدل‌ها حرکت کنید و جزئیات هر دستگاه را ببینید.')}<div class="exhibition-tabs" aria-label="خانواده‌های نمایشگاه">${cats.slice(0,full?8:4).map(c=>`<button data-exhibit-cat="${c[0]}" aria-pressed="${cat===c[0]}">${icon(c[3])}<span>${c[1]}</span></button>`).join('')}</div><div class="exhibition-body"><div class="exhibition-stage"><div class="stage-ruler"><span>SAHAND / EQUIPMENT VIEW</span><span id="exhibit-code">${E(p.code)}</span></div><button class="exhibit-image zoom-image" id="exhibit-zoom" data-zoom="${E(p.image)}" data-alt="${E(p.name)}" aria-label="نمایش تصویر کامل محصول">${image(p,'',true)}</button><div class="stage-controls"><button class="icon-button" data-exhibit-prev aria-label="مدل قبلی">‹</button><span id="exhibit-position" role="status" aria-live="polite">${num(1)} / ${num(ps.length)}</span><button class="icon-button" data-exhibit-next aria-label="مدل بعدی">›</button><span class="stage-caption">تصویر کامل / بدون برش</span></div></div><div class="exhibit-copy"><span class="eyebrow" id="exhibit-category">${label(p.cat)}</span><h3 id="exhibit-name">${E(p.name)}</h3><p id="exhibit-description">${definitions[p.cat][1]}</p><label class="model-selector">انتخاب مدل<select id="exhibit-select">${ps.map(p=>`<option value="${E(p.code)}">${E(p.code)} — ${E(p.name)}</option>`).join('')}</select></label><div class="exhibit-actions"><a class="button primary" id="exhibit-details" href="${href(p.code)}">بررسی کامل محصول</a><button class="button secondary" id="exhibit-quote" data-quote="${E(p.code)}">استعلام این مدل</button></div><a id="exhibit-all" class="text-link" href="products.html?cat=${p.cat}">تمام مدل‌های این خانواده</a><div class="exhibit-annotation">${icon('layers')}<span>مدل و تصویر را بررسی کنید؛ پیکربندی نهایی بر اساس نیاز پروژه انتخاب می‌شود.</span></div></div></div></div></section>`;
  }
  function atlas8(full=false){return `<section class="atlas-section ${full?'atlas-full':''}" id="engineering-atlas" data-atlas><div class="shell">${intro8('INSIDE THE SYSTEM','دستگاه، یک سامانه است.','اجزا را لمس کنید. نقش هر بخش و نکات مهم برای بررسی آن را بشناسید.')}<div class="atlas-layout"><div class="atlas-drawing"><div class="atlas-topline"><span>SYSTEM ARCHITECTURE</span><span>FIBER LASER CUTTING</span></div><div class="blueprint"><svg class="machine-schematic" viewBox="0 0 900 520" role="img" aria-labelledby="schematic-title"><title id="schematic-title">نمای شماتیک اجزای سامانهٔ برش فایبر</title><defs><pattern id="engineering-grid" width="30" height="30" patternUnits="userSpaceOnUse"><path d="M30 0H0v30" fill="none" stroke="currentColor" stroke-opacity=".1"/></pattern><linearGradient id="machine-fill" x2="0" y2="1"><stop stop-color="#21322e"/><stop offset="1" stop-color="#101c1a"/></linearGradient></defs><rect width="900" height="520" fill="url(#engineering-grid)"/><g fill="url(#machine-fill)" stroke="#8fa99b" stroke-width="1.5"><path d="m345 278 282-73 140 89-285 91z"/><path d="m345 278 137 107v80l-137-106z"/><path d="m482 385 285-91v80l-285 91z"/><path d="m345 310 137 103 285-89" fill="none"/><path d="m370 275 123 92 243-78-114-69z"/><path d="m465 230 18-5 148 100-18 6z"/><path d="M465 230v-98l18-5v98M613 331v-98l18-6v98"/><path d="m465 132 148 101 18-6-148-100z"/><path d="m520 151 34 24v65l-17 17-17-27z"/><path d="m520 230 17 12 17-2M537 257v31"/><path d="m90 245 80-12 42 26v112l-81 13-41-27zM90 245l41 27 81-13M131 272v112"/><path d="M101 278h18m-18 15h18m-18 15h18m26-17 50-8m-50 21 50-8m-50 21 50-8" fill="none"/><path d="m175 405 88-20 48 30v73l-88 20-48-30zM175 405l48 30 88-20M223 435v73"/><path d="m748 193 62-16 34 23v72l-63 17-33-24zM748 193l33 24 63-17M781 217v72"/><path d="m756 201 25 17 52-14v39l-52 15-25-18z" fill="#243c32"/><path d="M799 280v95m-23 11 43-12M373 360v50m105 56v30m246-99v32" fill="none"/></g><g stroke="#536e63" stroke-width="1" fill="none"><path d="m390 276 121 84m-90-92 121 84m-90-92 121 84m-90-92 121 84m-90-92 121 84m-90-92 121 84"/><path d="M80 460H20V70h840v390h-25" stroke-dasharray="5 7"/></g><path class="fiber-route" d="M170 233V120q0-50 70-50h180q117 0 117 80" fill="none" stroke="#d8fb78" stroke-width="3" stroke-dasharray="7 9"/><path class="beam-route" d="M537 288v37" stroke="#d8fb78" stroke-width="4"/><circle cx="537" cy="325" r="6" fill="#d8fb78"/><path d="M270 390V348h115" fill="none" stroke="#5aaecb" stroke-width="2" stroke-dasharray="5 7"/></svg>${atlasParts8.map((part,i)=>`<button class="atlas-hotspot" style="--x:${part.x}%;--y:${part.y}%" data-part="${part.id}" aria-label="${part.name}" aria-pressed="${i===0}" aria-controls="atlas-detail"><span class="hotspot-dot"></span><span class="hotspot-label">${part.name}</span></button>`).join('')}</div><p class="schematic-caption">نمای شماتیک برای آشنایی با اجزا؛ نقشهٔ ابعادی یا پیکربندی یک مدل مشخص نیست.</p><div class="atlas-part-nav" aria-label="اجزای دستگاه">${atlasParts8.map((p,i)=>`<button data-part="${p.id}" aria-pressed="${i===0}">${p.name}</button>`).join('')}</div></div><div class="atlas-detail" id="atlas-detail" aria-live="polite">${partDetail8(atlasParts8[0])}</div></div>${full?`<div class="atlas-related">${heading('SYSTEM COMPONENTS','تجهیزات مرتبط با این سامانه.','','products.html')}<div class="product-grid">${['FS006','CH003','CC003','CTRL-FSCUT2000E'].map(c=>D.products.find(p=>p.code===c)).filter(Boolean).map(p=>card(p)).join('')}</div></div>`:''}</div></section>`;}
  function partDetail8(p){return `<span class="atlas-part-symbol">${icon(p.icon)}</span><span class="eyebrow">${p.en}</span><h3>${p.name}</h3><h4>${p.lead}</h4><p>${p.text}</p><div class="part-checks"><b>چه چیزهایی بررسی می‌شود؟</b>${p.check.map(t=>`<span>${icon('check')}${t}</span>`).join('')}</div><a class="button secondary" href="products.html?cat=${p.cat}">مشاهدهٔ تجهیزات مرتبط</a>`;}
  function filmCards8(){return film8.map((f,i)=>`<button class="film-card" data-film="${f.id}"><div class="film-card-art film-card-${i}">${playIcon8()}<span>${f.en}</span></div><div><span class="eyebrow">فیلم و معرفی</span><h3>${f.name}</h3><p>${f.text}</p><span class="film-watch">تماشای فیلم</span></div></button>`).join('');}
  function home8(){return `<section class="cinema-hero"><div class="cinema-backdrop"><video id="hero-film" muted playsinline preload="none" poster="${poster8}" aria-label="فیلم فرایند برش لیزر"><source src="${film8[0].url}" type="video/mp4"></video></div><div class="cinema-shade"></div><div class="cinema-topline shell"><span>ENGINEERING LIGHT.<br>SHAPING INDUSTRY.</span><span class="cinema-edition">SAHAND<br>EXPERIENCE</span></div><div class="cinema-content shell"><span class="eyebrow">نمایشگاه دیجیتال سهند لیزر</span><h1>نور را مهندسی کن.<br><em>تولید را شکل بده.</em></h1><p>دستگاه را ببینید، سازوکارش را بشناسید و برای کاربرد خودتان بررسی کنید. سفری از فناوری لیزر تا قطعهٔ نهایی.</p><div class="button-row"><a class="button primary" href="showroom.html">ورود به نمایشگاه</a><button class="button cinematic-play" data-hero-play aria-pressed="false">${playIcon8()}<span>پخش فیلم برش</span></button></div><p id="hero-video-status" role="status" class="video-status"></p></div><div class="cinema-bottom shell"><div><span class="scene-rule"></span><span>فرایند برش فایبر</span></div><a href="atlas.html">کاوش در اجزای دستگاه</a><a href="#exhibition" class="scroll-hint">ادامهٔ تجربه<span></span></a></div></section><section class="experience-intro shell"><p class="eyebrow">SEE IT. UNDERSTAND IT. CHOOSE IT.</p><h2>قبل از انتخاب،<br>واقعاً بشناسید.</h2><p>از نمایش کامل مدل‌ها تا بررسی نقش سورس، هد و سامانهٔ حرکت؛ اینجا تجهیزات را در کنار فرایند تولید می‌بینید.</p><div class="experience-paths"><a href="showroom.html">${icon('layers')}<span><b>دیدن دستگاه‌ها</b><small>نمایشگاه تصویری مدل‌ها</small></span></a><a href="atlas.html">${icon('head')}<span><b>شناخت سامانه</b><small>اطلس تعاملی اجزا</small></span></a><a href="films.html">${playIcon8()}<span><b>دیدن فرایند</b><small>فیلم‌های دستگاه و تجهیزات</small></span></a></div></section>${exhibition8()}${atlas8()}<section class="film-section shell">${intro8('MOTION TELLS THE STORY','فناوری را در حرکت ببینید.','فرایند تولید را از نزدیک ببینید.')}<div class="film-grid">${filmCards8()}</div><a class="text-link" href="films.html">ورود به اتاق فیلم</a></section><section class="experience-services"><div class="shell">${intro8('FROM EXPLORATION TO OPERATION','از شناخت، تا شروع کار.','انتخاب تجهیزات، راه‌اندازی و پشتیبانی فنی؛ ادامهٔ مسیر در کنار شما.')}<div class="service-ribbon"><a href="service.html?id=consulting"><span>${icon('search')}</span><h3>بررسی کاربرد</h3><p>شروع از قطعه، متریال و ظرفیت تولید.</p></a><a href="service.html?id=installation"><span>${icon('cut')}</span><h3>نصب و راه‌اندازی</h3><p>هماهنگی استقرار و آغاز کار با دستگاه.</p></a><a href="service.html?id=support"><span>${icon('parts')}</span><h3>همراهی فنی</h3><p>نگهداری، سرویس و تأمین تجهیزات مرتبط.</p></a></div></div></section><section class="section shell">${heading('THE LASER JOURNAL','دانش پشت فناوری.','','articles.html')}${articleCards(3)}</section>`;}
  function showroomPage8(){return breadcrumb('نمایشگاه دیجیتال')+`<section class="experience-page-intro shell"><span class="eyebrow">THE EQUIPMENT EXHIBITION</span><h1>تجهیزات را از نزدیک بشناسید.</h1><p>یک خانواده را انتخاب کنید و مدل‌ها را با تصویر کامل و مسیر مستقیم به جزئیات محصول ببینید.</p></section>`+exhibition8(true);}
  function atlasPage8(){return breadcrumb('اطلس فنی')+`<section class="experience-page-intro shell"><span class="eyebrow">THE ENGINEERING ATLAS</span><h1>پشت هر فرایند، یک سامانه است.</h1><p>در این نمای تعاملی، نقش اجزای یک سامانهٔ برش فایبر را مرور کنید.</p></section>`+atlas8(true);}
  function filmsPage8(){return breadcrumb('اتاق فیلم')+`<section class="experience-page-intro shell"><span class="eyebrow">THE FILM ROOM</span><h1>تماشای فرایند.<br>شناختِ فناوری.</h1><p>فیلم‌های دستگاه، خط محصول و اجزای فنی را در همین سایت ببینید.</p></section><section class="shell film-library">${film8.map((f,i)=>`<article class="film-library-item"><div class="library-video"><video controls playsinline preload="none" poster="${poster8}" aria-label="${f.name}"><source src="${f.url}" type="video/mp4"></video></div><div><span class="eyebrow">${f.en}</span><h2>${f.name}</h2><p>${f.text}</p><a class="text-link" href="${i===2?'atlas.html':'showroom.html'}">${i===2?'شناخت اجزای دستگاه':'دیدن خانوادهٔ دستگاه‌ها'}</a></div></article>`).join('')}</section>`;}
  function setupExperience8(){
    const dialog=document.createElement('dialog');dialog.id='film-dialog';dialog.setAttribute('aria-labelledby','film-dialog-title');dialog.innerHTML=`<div class="film-dialog-top"><h2 id="film-dialog-title"></h2><button type="button" class="icon-button film-close" aria-label="بستن فیلم">${icon('close')}</button></div><video controls playsinline preload="metadata"></video><p class="film-dialog-status" role="status"></p>`;document.body.appendChild(dialog);
    let movieFocus=null;dialog.addEventListener('close',()=>{const v=dialog.querySelector('video');v.pause();v.removeAttribute('src');v.load();movieFocus?.focus();});dialog.querySelector('.film-close').onclick=()=>dialog.close();
    dialog.addEventListener('click',e=>{if(e.target===dialog){const b=dialog.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)dialog.close();}});
    dialog.querySelector('video').addEventListener('error',()=>{dialog.querySelector('.film-dialog-status').innerHTML='بارگذاری فیلم انجام نشد. <a href="films.html">فیلم را در اتاق فیلم باز کنید.</a>';});
    document.addEventListener('click',async e=>{
      const f=e.target.closest('[data-film]');if(f){const film=film8.find(x=>x.id===f.dataset.film);if(!film)return;movieFocus=f;dialog.querySelector('h2').textContent=film.name;dialog.querySelector('.film-dialog-status').innerHTML=E(film.text)+' <a href="'+E(film.url)+'" target="_blank" rel="noopener">باز کردن فیلم اصلی</a>';const v=dialog.querySelector('video');v.src=film.url;dialog.showModal();if(v.canPlayType('video/mp4; codecs="avc1.42E01E"')){try{await v.play();}catch{/* Native controls and the direct film link remain available. */}}return;}
      const h=e.target.closest('[data-hero-play]');if(h){const v=document.getElementById('hero-film');if(!v.canPlayType('video/mp4; codecs="avc1.42E01E"')){document.getElementById('hero-video-status').innerHTML='برای این مرورگر، <a href="'+film8[0].url+'" target="_blank" rel="noopener">فیلم اصلی را باز کنید</a> یا به <a href="films.html">اتاق فیلم</a> بروید.';return;}if(v.paused){h.disabled=true;document.getElementById('hero-video-status').textContent='در حال آماده‌سازی فیلم…';try{await Promise.race([v.play(),new Promise((_,reject)=>setTimeout(()=>reject(new Error('loading timeout')),12000))]);h.setAttribute('aria-pressed','true');h.querySelector('span').textContent='توقف فیلم';document.getElementById('hero-video-status').textContent='';}catch{document.getElementById('hero-video-status').innerHTML='برای دیدن فیلم به <a href="films.html">اتاق فیلم</a> بروید.';}finally{h.disabled=false;}}else{v.pause();h.setAttribute('aria-pressed','false');h.querySelector('span').textContent='ادامهٔ فیلم';}return;}
      const part=e.target.closest('[data-part]');if(part){const p=atlasParts8.find(x=>x.id===part.dataset.part);document.querySelectorAll('[data-part]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.part===p.id)));document.getElementById('atlas-detail').innerHTML=partDetail8(p);}
    });
    const showroom=document.querySelector('[data-showroom]');if(showroom){let family=counts[params.get('cat')]?params.get('cat'):'cutting';let models=D.products.filter(p=>p.cat===family),current=0;const select=document.getElementById('exhibit-select');
      function showModel(){const p=models[current];document.getElementById('exhibit-code').textContent=p.code;document.getElementById('exhibit-position').textContent=num(current+1)+' / '+num(models.length);document.getElementById('exhibit-category').textContent=label(p.cat);document.getElementById('exhibit-name').textContent=p.name;document.getElementById('exhibit-description').textContent=definitions[p.cat][1];const zoom=document.getElementById('exhibit-zoom');zoom.innerHTML=image(p,'',true);zoom.dataset.zoom=p.image;zoom.dataset.alt=p.name;document.getElementById('exhibit-details').href=href(p.code);document.getElementById('exhibit-quote').dataset.quote=p.code;document.getElementById('exhibit-all').href='products.html?cat='+p.cat;select.value=p.code;}
      showroom.addEventListener('click',e=>{const c=e.target.closest('[data-exhibit-cat]');if(c){family=c.dataset.exhibitCat;models=D.products.filter(p=>p.cat===family);current=0;select.innerHTML=models.map(p=>`<option value="${E(p.code)}">${E(p.code)} — ${E(p.name)}</option>`).join('');showroom.querySelectorAll('[data-exhibit-cat]').forEach(b=>b.setAttribute('aria-pressed',String(b===c)));if(route==='showroom'){const u=new URL(location.href);u.searchParams.set('cat',family);history.replaceState(null,'',u);}showModel();}if(e.target.closest('[data-exhibit-prev]')){current=(current-1+models.length)%models.length;showModel();}if(e.target.closest('[data-exhibit-next]')){current=(current+1)%models.length;showModel();}});
      select.addEventListener('change',()=>{current=models.findIndex(p=>p.code===select.value);showModel();});
    }
    document.querySelectorAll('.library-video').forEach(box=>{const video=box.querySelector('video'),link=document.createElement('a');link.className='direct-film-link';link.href=video.querySelector('source').src;link.target='_blank';link.rel='noopener';link.textContent='باز کردن فیلم اصلی';box.nextElementSibling.appendChild(link);});
    document.querySelectorAll('video').forEach(v=>{v.addEventListener('play',()=>document.querySelectorAll('video').forEach(other=>{if(other!==v)other.pause();}));});
    if(route==='product'){const p=D.products.find(p=>p.code===params.get('code'));if(p){const link=document.createElement('a');link.className='technical-atlas-link';link.href='atlas.html';link.innerHTML=icon('head')+'<span>این سامانه چگونه کار می‌کند؟<small>کاوش در اطلس فنی تجهیزات</small></span>';document.querySelector('.detail-copy')?.appendChild(link);}}
  }

