    const def=definitions[p.cat],power=p.name.match(/(\d+)\s*وات/),model=p.name.match(/(?:SH\d+[A-Z]?|CWFL-\d+|HL-\d+|RFL-[\w/-]+|FSCUT\w+|BM\w+|BT\w+|ITV\d+|QG-[\w-]+)/i);
